export type PresetKey = 'SUBHANALLAH' | 'ALHAMDULILLAH' | 'ALLAHU_AKBAR' | 'CENTURY' | 'UNLIMITED';

export interface DhikrPreset {
  id: PresetKey;
  label: string;
  arabic: string;
  meaning: string;
  virtue: string;
  target: number | null;
}

export interface AppState {
  count: number;
  selectedPresetId: PresetKey;
  isDarkMode: boolean;
  hapticsEnabled: boolean;
}

import { DhikrPreset } from './types';

export const DHIKR_PRESETS: Record<string, DhikrPreset> = {
  SUBHANALLAH: {
    id: 'SUBHANALLAH',
    label: 'SubhanAllah',
    arabic: 'سُبْحَانَ اللهِ',
    meaning: 'Glory be to Allah',
    virtue: 'A palm tree is planted for you in Paradise for every utterance.',
    target: 33,
  },
  ALHAMDULILLAH: {
    id: 'ALHAMDULILLAH',
    label: 'Alhamdulillah',
    arabic: 'الْحَمْدُ لِلَّهِ',
    meaning: 'Praise be to Allah',
    virtue: 'The utterance of Al-Hamdulillah fills the scale of good deeds.',
    target: 33,
  },
  ALLAHU_AKBAR: {
    id: 'ALLAHU_AKBAR',
    label: 'Allahu Akbar',
    arabic: 'اللهُ أَكْبَرُ',
    meaning: 'Allah is the Greatest',
    virtue: 'Reciting this 34 times before sleep is better than having a servant.',
    target: 34,
  },
