import React, { useState, useEffect, useCallback } from 'react';
import { DHIKR_PRESETS } from './constants';
import { PresetKey, AppState } from './types';
import { Header } from './components/Header';
import { CounterDisplay } from './components/CounterDisplay';
import { PresetSelector } from './components/PresetSelector';
import { VirtueDisplay } from './components/VirtueDisplay';
import { Controls } from './components/Controls';

const STORAGE_KEY = 'zen_tasbih_state_v1';

const App: React.FC = () => {
  // Initialize state from localStorage
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error("Failed to parse saved state", e);
      }
    }
    return {
      count: 0,
      selectedPresetId: 'SUBHANALLAH',
      isDarkMode: false,
      hapticsEnabled: true,
    };
  });

  // Persist state on changes
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const currentPreset = DHIKR_PRESETS[state.selectedPresetId];

  const handleIncrement = useCallback(() => {
    setState(prev => {
      const nextCount = prev.count + 1;

      // Haptic feedback
      if (prev.hapticsEnabled && window.navigator.vibrate) {
        // Subtle vibration
        window.navigator.vibrate(40);
      }

      // Check if target reached for notification-like feedback
      const target = DHIKR_PRESETS[prev.selectedPresetId].target;
      if (target && nextCount === target) {
        if (prev.hapticsEnabled && window.navigator.vibrate) {
           window.navigator.vibrate([100, 50, 100]); // Special vibe for target
        }
      }

      return { ...prev, count: nextCount };
    });
  }, []);

  const handleReset = useCallback(() => {
    if (confirm("Would you like to reset your current count?")) {
      setState(prev => ({ ...prev, count: 0 }));
    }
  }, []);

  const handlePresetChange = (id: PresetKey) => {
    setState(prev => ({ ...prev, selectedPresetId: id, count: 0 }));
  };

  const toggleDarkMode = () => {
    setState(prev => ({ ...prev, isDarkMode: !prev.isDarkMode }));
  };

  const toggleHaptics = () => {
    setState(prev => ({ ...prev, hapticsEnabled: !prev.hapticsEnabled }));
  };

  return (
    <div className={`h-screen w-full transition-colors duration-500 flex flex-col items-center justify-between overflow-hidden ${state.isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-[#FDFCFB] text-slate-800'}`}>

      <Header 
        isDarkMode={state.isDarkMode} 
        onToggleTheme={toggleDarkMode} 
        hapticsEnabled={state.hapticsEnabled}
        onToggleHaptics={toggleHaptics}
      />

      <div className="flex-1 w-full flex flex-col items-center justify-center relative">
        {/* Massive Touch Target Overlay */}
        <div 
          onClick={handleIncrement}
          className="absolute inset-0 z-10 cursor-pointer active:opacity-90"
          aria-label="Tap to count"
        />

        <div className="z-20 pointer-events-none flex flex-col items-center">
          <CounterDisplay 
            count={state.count} 
            target={currentPreset.target} 
            isDarkMode={state.isDarkMode} 
            arabic={currentPreset.arabic}
          />

          <div className="mt-8 text-center px-6">
            <h2 className={`text-sm font-medium tracking-widest uppercase mb-1 ${state.isDarkMode ? 'text-emerald-400' : 'text-emerald-700'}`}>
              {currentPreset.label}
            </h2>
            <p className={`text-xs opacity-60`}>
              {state.count} / {currentPreset.target || '∞'}
            </p>
          </div>
        </div>
      </div>

      <div className="w-full z-30 flex flex-col items-center pb-8 pt-4 space-y-6">
        <PresetSelector 
          selectedId={state.selectedPresetId} 
          onSelect={handlePresetChange}
          isDarkMode={state.isDarkMode}
        />

        <VirtueDisplay 
          meaning={currentPreset.meaning} 
          virtue={currentPreset.virtue} 
          isDarkMode={state.isDarkMode}
        />

        <Controls onReset={handleReset} isDarkMode={state.isDarkMode} />
      </div>

    </div>
  );
};

export default App;

