import React, { useEffect, useState } from 'react';

interface CounterDisplayProps {
  count: number;
  target: number | null;
  isDarkMode: boolean;
  arabic: string;
}

export const CounterDisplay: React.FC<CounterDisplayProps> = ({ count, target, isDarkMode, arabic }) => {
  const [scale, setScale] = useState(1);

  // Animation effect on count change
  useEffect(() => {
    setScale(1.1);
    const timeout = setTimeout(() => setScale(1), 100);
    return () => clearTimeout(timeout);
  }, [count]);

  const radius = 90;
  const circumference = 2 * Math.PI * radius;
  const progress = target ? Math.min(count / target, 1) : 0;
  const offset = circumference - progress * circumference;

  return (
    <div className="relative flex items-center justify-center w-64 h-64">
      {/* Arabic Text Layer */}
      <div className={`absolute top-0 transition-opacity duration-700 font-poppins text-lg opacity-40 ${isDarkMode ? 'text-emerald-400' : 'text-emerald-800'}`}>
        {arabic}
      </div>

      {/* Progress Circle */}
      <svg className="absolute w-full h-full -rotate-90">
        <circle
          cx="50%"
          cy="50%"
          r={radius}
          className={`fill-none stroke-current opacity-5 ${isDarkMode ? 'text-slate-100' : 'text-slate-900'}`}
          strokeWidth="4"
        />
        <circle
          cx="50%"
          cy="50%"
          r={radius}
          className={`fill-none transition-all duration-300 ease-out stroke-current ${isDarkMode ? 'text-emerald-500' : 'text-emerald-600'}`}
          strokeWidth="4"
          strokeDasharray={circumference}
          strokeDashoffset={target ? offset : circumference}
          strokeLinecap="round"
        />
      </svg>

      {/* Actual Count */}
      <div 
        className="text-7xl font-light tabular-nums font-poppins transition-transform duration-100 ease-out"
        style={{ transform: `scale(${scale})` }}
      >
        {count}
      </div>
    </div>
  );
};

