import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GoogleGenAI, Modality } from "@google/genai";
import { DHIKR_PRESETS } from './constants';
import { PresetKey, AppState } from './types';
import { Header } from './components/Header';
import { CounterDisplay } from './components/CounterDisplay';
import { PresetSelector } from './components/PresetSelector';
import { VirtueDisplay } from './components/VirtueDisplay';
import { Controls } from './components/Controls';

const STORAGE_KEY = 'zen_tasbih_state_v2';

// Audio Utility Functions
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const App: React.FC = () => {
  const audioContextRef = useRef<AudioContext | null>(null);

  // Initialize state from localStorage
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error("Failed to parse saved state", e);
      }
    }
    return {
      count: 0,
      selectedPresetId: 'SUBHANALLAH',
      customTarget: 1000,
      isDarkMode: false,
      hapticsEnabled: true,
    };
  });

  // Persist state on changes
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const currentPreset = DHIKR_PRESETS[state.selectedPresetId];
  const effectiveTarget = state.selectedPresetId === 'CUSTOM' ? state.customTarget : currentPreset.target;

  const playCompletionVoice = async () => {
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: 'Say cheerfully: Subhan Allah' }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const audioBuffer = await decodeAudioData(
          decodeBase64(base64Audio),
          ctx,
          24000,
          1,
        );
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (e) {
      console.error("Failed to generate completion voice", e);
    }
  };

  const handleIncrement = useCallback(() => {
    setState(prev => {
      const nextCount = prev.count + 1;
      const target = prev.selectedPresetId === 'CUSTOM' ? prev.customTarget : DHIKR_PRESETS[prev.selectedPresetId].target;

      // Haptic feedback
      if (prev.hapticsEnabled && window.navigator.vibrate) {
        window.navigator.vibrate(40);
      }

      // Check if target reached
      if (target && nextCount === target) {
        if (prev.hapticsEnabled && window.navigator.vibrate) {
           window.navigator.vibrate([100, 50, 100]);
        }
        playCompletionVoice();
      }

      return { ...prev, count: nextCount };
    });
  }, [playCompletionVoice]);

  const handleReset = useCallback(() => {
    if (confirm("Would you like to reset your current count?")) {
      setState(prev => ({ ...prev, count: 0 }));
    }
  }, []);

  const handlePresetChange = (id: PresetKey) => {
    setState(prev => ({ ...prev, selectedPresetId: id, count: 0 }));
  };

  const handleCustomTargetChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value) || 0;
    setState(prev => ({ ...prev, customTarget: val }));
  };

  const toggleDarkMode = () => {
    setState(prev => ({ ...prev, isDarkMode: !prev.isDarkMode }));
  };

  const toggleHaptics = () => {
    setState(prev => ({ ...prev, hapticsEnabled: !prev.hapticsEnabled }));
  };

  return (
    <div className={`h-screen w-full transition-colors duration-500 flex flex-col items-center justify-between overflow-hidden ${state.isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-[#FDFCFB] text-slate-800'}`}>

      <Header 
        isDarkMode={state.isDarkMode} 
        onToggleTheme={toggleDarkMode} 
        hapticsEnabled={state.hapticsEnabled}
        onToggleHaptics={toggleHaptics}
      />

      <div className="flex-1 w-full flex flex-col items-center justify-center relative">
        <div 
          onClick={handleIncrement}
          className="absolute inset-0 z-10 cursor-pointer active:opacity-90"
          aria-label="Tap to count"
        />

        <div className="z-20 pointer-events-none flex flex-col items-center">
          <CounterDisplay 
            count={state.count} 
            target={effectiveTarget} 
            isDarkMode={state.isDarkMode} 
            arabic={currentPreset.arabic}
          />

          <div className="mt-8 text-center px-6">
            <h2 className={`text-sm font-medium tracking-widest uppercase mb-1 ${state.isDarkMode ? 'text-emerald-400' : 'text-emerald-700'}`}>
              {currentPreset.label}
            </h2>
            {state.selectedPresetId === 'CUSTOM' ? (
              <div className="flex items-center justify-center space-x-2 pointer-events-auto">
                <span className="text-xs opacity-60">{state.count} / </span>
                <input 
                  type="number"
                  value={state.customTarget}
                  onChange={handleCustomTargetChange}
                  className={`bg-transparent border-b border-dashed text-xs w-24 text-center focus:outline-none focus:border-emerald-500 transition-colors ${state.isDarkMode ? 'border-slate-700 text-slate-300' : 'border-slate-300 text-slate-600'}`}
                  placeholder="Set target..."
                  min="1"
                />
              </div>
            ) : (
              <p className={`text-xs opacity-60`}>
                {state.count} / {effectiveTarget || '∞'}
              </p>
            )}
          </div>
